const QR_QUIET_ZONE = 4;

const QR_VALUE = "https://mission-platform.dev";

export interface ScannerCase {
  readonly id: string;
  readonly width: number;
  readonly height: number;
  readonly image: ImageLike;
  readonly roi?: Roi;
  readonly expected: Readonly<{ format: "qr"; value: string }>;
}

function createFrame(
  width: number,
  height: number,
  moduleScale: number,
): { readonly image: ImageLike; readonly roi: Roi } {
  const data = new Uint8ClampedArray(width * height * 4);
  data.fill(255);
  const symbolWidth = (QR_MODULES[0].length + QR_QUIET_ZONE * 2) * moduleScale;
  const symbolHeight = (QR_MODULES.length + QR_QUIET_ZONE * 2) * moduleScale;
  const left = Math.floor((width - symbolWidth) / 2);
  const top = Math.floor((height - symbolHeight) / 2);
  for (const [moduleY, row] of QR_MODULES.entries()) {
    for (const [moduleX, value] of row.entries()) {
      if (!value) continue;
      for (let y = 0; y < moduleScale; y += 1) {
        for (let x = 0; x < moduleScale; x += 1) {
          const pixel =
            (top + (moduleY + QR_QUIET_ZONE) * moduleScale + y) * width +
            left +
            (moduleX + QR_QUIET_ZONE) * moduleScale +
            x;
          const offset = pixel * 4;
          data[offset] = 0;
          data[offset + 1] = 0;
          data[offset + 2] = 0;
          data[offset + 3] = 255;
        }
      }
    }
  }
  return {
    image: { width, height, data },
    roi: { x: left, y: top, width: symbolWidth, height: symbolHeight },
  };
}

export function createScannerCases(): readonly ScannerCase[] {
  const definitions = [
    { id: "qr-640x480-full", width: 640, height: 480, moduleScale: 8 },
    { id: "qr-640x480-roi", width: 640, height: 480, moduleScale: 8 },
    { id: "qr-1280x720-full", width: 1280, height: 720, moduleScale: 12 },
    { id: "qr-1280x720-roi", width: 1280, height: 720, moduleScale: 12 },
  ] as const;
  return definitions.map(({ id, width, height, moduleScale }) => {
    const { image, roi } = createFrame(width, height, moduleScale);
    return {
      id,
      width,
      height,
      image,
      ...(id.endsWith("-roi") ? { roi } : {}),
      expected: { format: "qr", value: QR_VALUE },
    } satisfies ScannerCase;
  });
}
